/**
 * Page-side scripts used by both browser surfaces.
 *
 * Everything here returns plain JSON so results survive CDP serialisation. The
 * selectors are built from tags and `:nth-of-type` rather than class names:
 * class names are generated by build tools and change between deploys, which
 * would make a saved assertion break for no reason.
 *
 * **Targets, not just selectors.** A positional selector is unusable on a page
 * built from component-library wrappers: a Naive UI form puts every label and
 * its input inside a wrapper that is not a sibling of anything the snapshot can
 * express, and `:nth-of-type` chains that long break as soon as one conditional
 * field appears. A person does not read those paths either — they look at the
 * label. So every action accepts a semantic target (label / text / role) and
 * resolves it in the page, falling back to a CSS selector when one is given.
 */

export interface ElementTarget {
  selector?: string;
  /** Text of the visible label next to a form field ("用户名"). */
  label?: string;
  /** Text of a button, link or other interactive element ("创建租户"). */
  text?: string;
  /** ARIA role, used to disambiguate ("button", "combobox"). */
  role?: string;
  /** Require an exact match instead of a prefix / substring match. */
  exact?: boolean;
  /**
   * 收窄字段：元素自身可见文本包含该子串。
   *
   * 与 `text` 不同，`text` 参与打分排名，`hasText` 是硬过滤——过滤后剩下的每个
   * 都算命中。比较先做空白归一再转小写，所以「B」也能排掉「b」。
   */
  hasText?: string;
  /** 收窄字段：元素自身可见文本不包含该子串。 */
  hasNotText?: string;
  /** 收窄字段：true 只留可见元素，false 只留不可见元素。 */
  visible?: boolean;
  /**
   * 匹配多个时取第几个。0 起，负数从尾数（-1 是最后一个）。
   *
   * 不给时单目标解析取排名第一的（与历史行为一致）；句柄路径不给 nth 会按
   * 「登记/上次命中的文本特征」对齐，对不齐才报「匹配 N 个」。
   */
  nth?: number;
  /**
   * `find_browser_element` 登记的句柄 id。
   *
   * 只在 main 层被解释（查该标签页的句柄表，换出存储的定位描述符），页内脚本
   * 从不读这个字段。与 selector / label / text / role 互斥。
   */
  handle?: string;
}

/** Shorthand: a bare string is a CSS selector. */
export type TargetInput = string | ElementTarget;

/** One entry of a find preview: what the caller needs to pick between matches. */
export interface ElementMatch {
  tag: string;
  /** 元素可见文本，截断到 80 字符；也是句柄特征对齐用的那一串。 */
  text: string;
  visible: boolean;
  rect: { x: number; y: number; width: number; height: number };
}

/**
 * 一次收窄定位的完整结果。
 *
 * `ok: false` 时 `reason` 说明为什么没有选出唯一元素——找不到、多个且无法决定、
 * nth 越界或选择器无效。调用方（main 层）把这些 reason 映射成面向模型的报错
 * （见本文件的 `locatorErrorText`），页内脚本只报告事实。
 */
export interface LocatorMatches {
  ok: boolean;
  reason?: "not-found" | "ambiguous" | "nth-out-of-range" | "invalid-selector" | "no-target";
  /** 应用收窄字段之后的匹配总数。 */
  count: number;
  /** 实际选中的匹配下标（ok: true 时存在）。 */
  index?: number;
  matchedBy?: string;
  /** 全部匹配的预览（上限 50 条；count 仍是真实总数）。 */
  matches: ElementMatch[];
  /** 选中的那一条，省得调用方再按 index 查一次。 */
  picked?: ElementMatch;
}

export interface FindLocatorOptions {
  /**
   * 使用句柄时的对齐特征：登记或上次命中时选中元素的文本。在当前匹配里恰好
   * 只有一个的文本与之相同时选它——重渲染换掉 DOM 节点、打乱顺序之后，
   * 「同一定位 + 同一文本」仍然指向同一逻辑元素。
   */
  trait?: string;
  /** 显式取第几个（0 起，负数从尾数）；给了一定按位置取，覆盖 trait。 */
  nth?: number;
  /**
   * 登记模式：只要有一个匹配就按 nth（默认 0）定位，不做多匹配判定。
   * find 工具要允许「先看到有 N 个」再决定收窄，所以登记时不因多匹配报错。
   */
  first?: boolean;
}

export interface DomSnapshotNode {
  role: string;
  name: string;
  tag: string;
  selector: string;
  /**
   * Text of the label a person would read next to this control. Filled for form
   * fields even when the control has no accessible name of its own (a component
   * library's selection box shows the chosen value, not its field label).
   */
  field?: string;
  bounds: { x: number; y: number; width: number; height: number };
  /**
   * Index of the nearest reported ancestor in `nodes`, or absent for a root.
   *
   * The list stays flat because every consumer already treats it as a list, and
   * a nested tree would double the payload on pages that are mostly text. What
   * was missing is *enough* structure to answer "which dialog is this button
   * in": a parent index gets that for one integer, and a caller that does not
   * care can ignore it.
   *
   * It points at the nearest ancestor that survived the same filter (visible,
   * interactive / heading / text leaf), not necessarily the DOM parent: the
   * skipped levels carry no information the model can use.
   */
  parent?: number;
  /** Distance from the nearest reported root; 0 for a top-level node. */
  depth?: number;
}

export interface DomSnapshot {
  url: string;
  title: string;
  viewport: { width: number; height: number };
  nodes: DomSnapshotNode[];
  /** Total visible elements considered before the cap was applied. */
  total: number;
  truncated: boolean;
}

export interface ElementPoint {
  ok: boolean;
  reason?: string;
  x?: number;
  y?: number;
  width?: number;
  height?: number;
  tag?: string;
  text?: string;
  /** Selector of the element that was actually resolved. */
  selector?: string;
  matchedBy?: string;
  /**
   * 收窄后的匹配总数。直连动作取排名第一的元素不变，但上层据此在 count > 1 时
   * 附一条非致命 warning（「匹配 N 个，已操作第 1 个」）。
   */
  matchCount?: number;
}

export interface VisibilityProbe {
  exists: boolean;
  visible: boolean;
  reason?: string;
  bounds?: { x: number; y: number; width: number; height: number };
  selector?: string;
  name?: string;
}

/**
 * What a `wait` can wait for.
 *
 * `network-idle` and `response` are the odd ones out: the first five are
 * page-DOM facts, and these two are facts about the page's request activity,
 * read from the collector in `page-log.ts`. `load` stays here because it is a
 * DOM fact (`document.readyState`), just one about the document's lifecycle
 * rather than its content. They are all in one list because callers pick a wait
 * by intent — "until this settled" — not by which internal module answers it.
 */
export type WaitCondition =
  | "visible"
  | "hidden"
  | "text"
  | "url"
  | "value"
  | "network-idle"
  | "load"
  | "response";

export interface WaitResult {
  ok: boolean;
  waitedMs: number;
  timedOut?: boolean;
  /**
   * Which deadline ran out, when one did.
   *
   * `"page"` means the in-page poll loop reached its own deadline and reports
   * the real reason in `reason` (`url-mismatch`, `text-absent`, …) — the
   * condition genuinely did not hold. `"bridge"` means the page never answered
   * at all before this side gave up, which is a different diagnosis: the page is
   * throttled, frozen or stuck, and retrying with the same condition will
   * probably behave the same way.
   *
   * The two were indistinguishable before — both arrived as `evaluate-timeout`,
   * and a caller could not tell "the toast never appeared" from "the tab stopped
   * responding".
   */
  timedOutAt?: "page" | "bridge";
  reason?: string;
  /**
   * What was matched, for the caller's log: the URL for `url`, the readyState
   * (`"complete"`) for `load`, the match reason for element conditions — so the
   * caller can tell which condition released the wait.
   */
  matched?: string;
}

/**
 * Shared helpers injected into every script: visibility, accessible name, a
 * stable selector path, and the semantic target resolver. Kept as a string so
 * it can be embedded in each expression without a build step.
 */
const HELPERS = `
  // Walks every root the page actually renders into: the document, each open
  // shadow root (recursively), and each same-origin iframe's document. Admin
  // consoles increasingly mount controls inside web components or editor
  // iframes; a document-only query misses them, which reads to the caller as
  // "the control does not exist". Cross-origin iframes are separate processes
  // (OOPIF) and stay out of reach of page script — a known boundary, not a bug.
  const eachRoot = (visit) => {
    const walkDocument = (doc) => {
      visit(doc);
      doc.querySelectorAll("*").forEach((el) => {
        if (el.shadowRoot) walkDocument(el.shadowRoot);
        if (el.tagName === "IFRAME") {
          try {
            const inner = el.contentDocument;
            if (inner && inner.body) walkDocument(inner);
          } catch {}
        }
      });
    };
    walkDocument(document);
  };
  const deepQueryAll = (selector) => {
    const out = [];
    eachRoot((root) => {
      try { root.querySelectorAll(selector).forEach((el) => out.push(el)); } catch {}
    });
    return out;
  };
  const isVisible = (el) => {
    if (!el || el.nodeType !== 1) return false;
    const style = getComputedStyle(el);
    if (style.visibility === "hidden" || style.display === "none") return false;
    if (Number(style.opacity) === 0) return false;
    if (el.hasAttribute("hidden") || el.getAttribute("aria-hidden") === "true") return false;
    const rect = el.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) return false;
    // A fully transparent parent (common in "visibility toggles") still counts as
    // invisible: checkVisibility covers the ancestors in one call where supported.
    if (typeof el.checkVisibility === "function") {
      try {
        if (!el.checkVisibility({ checkOpacity: true, checkVisibilityCSS: true })) return false;
      } catch {}
    }
    return true;
  };
  const textOf = (el) => {
    const raw = (el.innerText || el.textContent || "").replace(/\\s+/g, " ").trim();
    return raw;
  };
  // 元素自己的文字：只数直接挂在它下面的文本节点，不含子孙带进来的。「有自身
  // 文字」是 text 定位候选池的入池条件——容器（body、包着一串孩子的 div）因此
  // 天然落选，不会让整页陪着同一个词命中。
  const ownTextOf = (el) => {
    let out = "";
    for (const node of el.childNodes) {
      if (node.nodeType === 3) out += node.textContent || "";
    }
    return out.replace(/\\s+/g, " ").trim();
  };
  const labelOf = (el) => {
    const aria = el.getAttribute("aria-label");
    if (aria && aria.trim()) return aria.trim();
    const labelledBy = el.getAttribute("aria-labelledby");
    if (labelledBy) {
      const parts = [];
      for (const id of labelledBy.split(/\\s+/)) {
        const node = document.getElementById(id);
        if (node) parts.push(textOf(node));
      }
      const joined = parts.join(" ").trim();
      if (joined) return joined;
    }
    if (el.labels && el.labels.length) {
      const joined = Array.from(el.labels).map(textOf).join(" ").trim();
      if (joined) return joined;
    }
    return "";
  };
  const nameOf = (el) => {
    const label = labelOf(el);
    if (label) return label;
    const tag = el.tagName.toLowerCase();
    if (tag === "input" || tag === "textarea" || tag === "select") {
      return (
        el.getAttribute("placeholder") ||
        el.getAttribute("title") ||
        el.getAttribute("name") ||
        el.getAttribute("type") ||
        tag
      ).trim();
    }
    if (tag === "img") return (el.getAttribute("alt") || "").trim();
    return textOf(el);
  };
  const roleOf = (el) => {
    const explicit = (el.getAttribute("role") || "").trim();
    if (explicit) return explicit;
    const tag = el.tagName.toLowerCase();
    if (tag === "a") return el.hasAttribute("href") ? "link" : "text";
    if (tag === "button") return "button";
    if (tag === "select") return "combobox";
    if (tag === "textarea") return "textbox";
    if (tag === "input") {
      const type = (el.getAttribute("type") || "text").toLowerCase();
      if (type === "checkbox" || type === "radio") return type;
      if (type === "submit" || type === "button" || type === "reset") return "button";
      return "textbox";
    }
    if (/^h[1-6]$/.test(tag)) return "heading";
    if (tag === "li") return "listitem";
    if (tag === "table") return "table";
    if (tag === "tr") return "row";
    if (tag === "td" || tag === "th") return "cell";
    return "text";
  };
  const INTERACTIVE = 'a[href],button,input,select,textarea,summary,[role],[onclick],[tabindex]:not([tabindex="-1"])';
  const CONTROLS = 'input:not([type=hidden]),textarea,select,[contenteditable="true"],[role=textbox],[role=combobox],[role=searchbox]';
  const LABELISH = 'label,legend,dt,th,[role=columnheader],[class*="label"],[class*="Label"],[class*="title"],[class*="Title"]';
  const norm = (value) => String(value || "").replace(/\\s+/g, " ").trim().toLowerCase();
  const scoreName = (candidate, wanted, exact) => {
    const a = norm(candidate);
    const b = norm(wanted);
    if (!a || !b) return 0;
    if (a === b) return 100;
    if (exact) return 0;
    if (a.startsWith(b)) return 70;
    if (a.includes(b)) return 40;
    return 0;
  };
  const scriptPath = (el) => {
    if (el.id) {
      try {
        if (document.querySelectorAll("#" + CSS.escape(el.id)).length === 1) {
          return "#" + CSS.escape(el.id);
        }
      } catch {}
    }
    // Attributes an application sets on purpose survive a re-render; generated
    // class names do not. Try those before falling back to a positional path.
    for (const attr of ["data-testid", "data-test", "data-cy"]) {
      const value = el.getAttribute(attr);
      if (value) {
        const selector = el.tagName.toLowerCase() + "[" + attr + '="' + CSS.escape(value) + '"]';
        try {
          if (document.querySelectorAll(selector).length === 1) return selector;
        } catch {}
      }
    }
    const name = el.getAttribute("name");
    if (name) {
      const selector = el.tagName.toLowerCase() + '[name="' + CSS.escape(name) + '"]';
      try {
        if (document.querySelectorAll(selector).length === 1) return selector;
      } catch {}
    }
    const parts = [];
    let node = el;
    while (node && node.nodeType === 1 && node !== document.documentElement) {
      let part = node.tagName.toLowerCase();
      const parent = node.parentElement;
      if (parent) {
        const siblings = Array.from(parent.children).filter((child) => child.tagName === node.tagName);
        if (siblings.length > 1) part += ":nth-of-type(" + (siblings.indexOf(node) + 1) + ")";
      }
      parts.unshift(part);
      if (parts.length >= 7) break;
      node = parent;
    }
    return parts.join(" > ");
  };
  const rectOf = (el) => {
    const rect = el.getBoundingClientRect();
    return { x: Math.round(rect.x), y: Math.round(rect.y), width: Math.round(rect.width), height: Math.round(rect.height) };
  };
  /**
   * DOM closeness between a label anchor and a candidate control, as three
   * ordered keys: tree distance first, then how far apart the two branches sit
   * under their common ancestor, then a preference for a control that comes
   * after the label (labels precede their fields in most forms, including
   * wrapper-less ones). A tie across all three means the DOM genuinely cannot
   * say which field the label names — the caller must decline rather than
   * guess, because a wrong guess writes one field's value into another.
   */
  const domRank = (a, b) => {
    if (a === b) return { dist: 0, spread: 0, after: 0 };
    const ancestors = new Map();
    let node = a;
    for (let d = 0; node; d += 1, node = node.parentElement) ancestors.set(node, d);
    let other = b;
    let steps = 0;
    let common = null;
    while (other) {
      if (ancestors.has(other)) { common = other; break; }
      steps += 1;
      other = other.parentElement;
    }
    if (!common) return null;
    const branch = (el) => {
      let n = el;
      while (n && n.parentElement !== common) n = n.parentElement;
      return n ? Array.prototype.indexOf.call(common.children, n) : -1;
    };
    return {
      dist: ancestors.get(common) + steps,
      spread: Math.abs(branch(a) - branch(b)),
      after: branch(b) - branch(a),
    };
  };
  const closerRank = (x, y) => {
    if (x.dist !== y.dist) return x.dist < y.dist;
    if (x.spread !== y.spread) return x.spread < y.spread;
    const tx = x.after >= 0 ? x.after : 100 - x.after;
    const ty = y.after >= 0 ? y.after : 100 - y.after;
    return tx < ty;
  };
  /**
   * Resolves a label to every control it could describe, best first.
   *
   * Three shapes cover the libraries in use: <label for>, a control wrapped by
   * its <label>, and a wrapper that holds both the label and the control (Naive
   * UI, Ant Design, Element Plus). The last one climbs from the label until it
   * reaches a scope with exactly one visible control; a scope with many controls
   * only wins while its own text still mentions the label, and then claims the
   * control closest to the label rather than the first in document order —
   * "closest" is what keeps a three-field bare form (label, input, label,
   * textarea, label, select, all siblings) from resolving every label to the
   * same first control and typing one field's value into another.
   *
   * The first entry is exactly what the single-target resolver has always taken;
   * the whole list is what the find tools need to report "this label names two
   * controls" instead of silently picking one. The same loop produces both.
   */
  const labelControls = (wanted, exact) => {
    const anchors = deepQueryAll(LABELISH).filter(isVisible);
    const ranked = [];
    for (const el of anchors) {
      const score = scoreName(textOf(el), wanted, exact);
      if (score > 0) ranked.push({ el, score });
    }
    ranked.sort((a, b) => b.score - a.score);
    const out = [];
    const seen = new Set();
    const push = (el) => {
      if (el && !seen.has(el)) { seen.add(el); out.push(el); }
    };
    for (const item of ranked.slice(0, 6)) {
      const anchor = item.el;
      const own = anchor.control || anchor.querySelector(CONTROLS);
      if (own && isVisible(own)) { push(own); continue; }
      let scope = anchor.parentElement;
      for (let depth = 0; scope && depth < 6; depth += 1, scope = scope.parentElement) {
        const controls = Array.from(scope.querySelectorAll(CONTROLS)).filter(isVisible);
        if (controls.length === 1) { push(controls[0]); break; }
        if (controls.length > 1 && scoreName(textOf(scope), wanted, exact) > 0) {
          let best = null;
          for (const control of controls) {
            const rank = domRank(anchor, control);
            if (rank && (!best || closerRank(rank, best.rank))) best = { control, rank };
          }
          if (best) push(best.control);
          break;
        }
      }
    }
    return out;
  };
  /**
   * Applies the narrowing fields (hasText / hasNotText / visible) to a candidate
   * list. Order is preserved; the caller decides which entry to take. A bare
   * candidate list passes through untouched, which is what keeps every existing
   * caller's behaviour byte-for-byte identical.
   */
  const filterNarrow = (els, spec) => {
    let out = els;
    if (spec.hasText) {
      const needle = norm(spec.hasText);
      if (needle) out = out.filter((el) => norm(textOf(el)).includes(needle));
    }
    if (spec.hasNotText) {
      const needle = norm(spec.hasNotText);
      if (needle) out = out.filter((el) => !norm(textOf(el)).includes(needle));
    }
    if (spec.visible === true) out = out.filter(isVisible);
    else if (spec.visible === false) out = out.filter((el) => !isVisible(el));
    return out;
  };
  /**
   * Resolves a locator to every element it names, best first, narrowing applied.
   *
   * resolveTarget below is "take one entry of this list"; the find tools are
   * "report the whole list". One implementation for both is what makes them
   * agree on which element a locator names — the historical failure mode was two
   * resolvers drifting apart, where the finder saw one element and the actor
   * clicked another.
   */
  const collectMatches = (target) => {
    if (typeof target === "string") target = { selector: target };
    if (!target) return { matches: [], reason: "no-target" };
    if (target.selector) {
      let els;
      try { els = deepQueryAll(target.selector); } catch { return { matches: [], reason: "invalid-selector" }; }
      return { matches: filterNarrow(els, target), matchedBy: "selector" };
    }
    if (target.label) {
      const matches = filterNarrow(labelControls(target.label, target.exact === true), target);
      if (matches.length) return { matches, matchedBy: "label" };
    }
    if (target.text || target.role) {
      // 候选池 = 可交互元素 ∪ 有非空自身文字的可见元素。text 要点的常常是按钮，
      // 但要读、要等的目标（一个会消失的盒子、一个 li）不一定是控件——只扫交互
      // 元素会让 text 定位对纯展示元素报「不存在」。保持文档序遍历：交互元素
      // 之间的相对顺序与只扫 INTERACTIVE 时完全一致。
      const pool = [];
      eachRoot((root) => {
        try {
          root.querySelectorAll("*").forEach((el) => {
            if (!isVisible(el)) return;
            if (el.matches(INTERACTIVE) || ownTextOf(el)) pool.push(el);
          });
        } catch {}
      });
      const ranked = [];
      for (const el of pool) {
        if (target.role && roleOf(el) !== target.role) continue;
        let score = 0;
        if (target.text) {
          score = Math.max(
            scoreName(nameOf(el), target.text, target.exact === true),
            scoreName(textOf(el), target.text, target.exact === true),
          );
        } else {
          score = 1;
        }
        if (score > 0) ranked.push({ el, score });
      }
      ranked.sort((a, b) => b.score - a.score);
      const matches = filterNarrow(ranked.map((item) => item.el), target);
      if (matches.length) return { matches, matchedBy: target.text ? "text" : "role" };
    }
    return { matches: [], reason: "not-found" };
  };
  /** Picks a position in a match list: nth (negative from the end) or first. */
  const pickFromMatches = (count, nth) => {
    if (typeof nth !== "number" || !Number.isFinite(nth)) return 0;
    const i = nth < 0 ? count + Math.trunc(nth) : Math.trunc(nth);
    return i >= 0 && i < count ? i : -1;
  };
  const resolveTarget = (target) => {
    const spec = typeof target === "string" ? { selector: target } : target;
    const found = collectMatches(spec);
    if (!found.matches.length) return { reason: found.reason || "not-found" };
    const index = pickFromMatches(found.matches.length, spec ? spec.nth : undefined);
    if (index < 0) return { reason: "nth-out-of-range" };
    // matchCount 随命中一起返回：直连动作保持「取排名第一个」的行为不变，但
    // 上层要据此给出非致命 warning（「匹配 N 个，已操作第 1 个」），没有这个数
    // 就编不出来。
    return {
      el: found.matches[index],
      matchedBy: found.matchedBy,
      matchCount: found.matches.length,
    };
  };
  /**
   * Finds the smallest visible element whose text matches.
   *
   * The regular resolver only searches interactive elements, which is right for
   * clicking and typing but wrong for reading: the order number somebody wants
   * captured lives in a paragraph, not a control. Deepest-first keeps a short
   * order number from resolving to the whole page, which also contains it.
   */
  const textElement = (wanted, exact) => {
    const all = [];
    eachRoot((root) => { try { root.querySelectorAll("*").forEach((el) => all.push(el)); } catch {} });
    let best = null;
    let bestScore = 0;
    for (const el of all) {
      if (!isVisible(el)) continue;
      const own = ownTextOf(el);
      const candidate = own ? own : el.children.length === 0 ? textOf(el) : "";
      if (!candidate) continue;
      const score = scoreName(candidate, wanted, exact);
      if (score === 0) continue;
      // Prefer a closer match, then the deeper element.
      const depth = (() => {
        let d = 0;
        let node = el;
        while (node && node.parentElement) {
          d += 1;
          node = node.parentElement;
        }
        return d;
      })();
      const weighted = score * 100 + depth;
      if (weighted > bestScore) {
        bestScore = weighted;
        best = el;
      }
    }
    return best;
  };
  /** The label a person reads next to this control, even without aria wiring. */
  const fieldLabelOf = (el) => {    const own = labelOf(el);
    if (own) return own;
    let scope = el.parentElement;
    for (let depth = 0; scope && depth < 5; depth += 1, scope = scope.parentElement) {
      const labels = Array.from(scope.querySelectorAll(LABELISH)).filter(isVisible);
      if (labels.length === 1) return textOf(labels[0]);
      if (labels.length > 1) return "";
    }
    return "";
  };
`;

/** Serialises a target into the page script without letting it inject code. */
function targetSource(target: TargetInput): string {
  return JSON.stringify(typeof target === "string" ? { selector: target } : target);
}

/** Human-readable name for an error message. */
export function describeTarget(target: TargetInput): string {
  if (typeof target === "string") return target;
  if (target.selector) return target.selector;
  if (target.label) return `标签「${target.label}」`;
  if (target.text) return `文本「${target.text}」`;
  if (target.role) return `role=${target.role}`;
  return "目标";
}

/**
 * Visible element inventory: interactive controls, headings and text blocks.
 *
 * Only what a user can see is reported, because the questions this answers are
 * "does this account see the delete button" and "what can this account do here".
 * Hidden markup is deliberately excluded — including it would make every account
 * look identical.
 */
export function buildDomSnapshotExpression(
  options: { maxNodes?: number; maxNameLength?: number } = {},
): string {
  const maxNodes = options.maxNodes ?? 400;
  const maxName = options.maxNameLength ?? 120;
  return `(() => {${HELPERS}
    const seen = new Set();
    const nodes = [];
    // Reported element to its index in "nodes", for resolving the parent link.
    const indexOf = new WeakMap();
    let total = 0;
    const all = [];
    eachRoot((root) => { try { root.querySelectorAll("*").forEach((el) => all.push(el)); } catch {} });
    // Elements are collected host-first (the outer document, then each shadow
    // root, then each iframe), so an ancestor that was reported is always
    // already indexed when its descendant arrives.
    const reportedParent = (el) => {
      let node = el.parentElement;
      let cur = el;
      for (let guard = 0; guard < 64; guard += 1) {
        if (node) return node;
        // Leave a shadow root through its host, and an iframe document through
        // the frame element: parentElement stops at both boundaries.
        const root = cur && typeof cur.getRootNode === "function" ? cur.getRootNode() : null;
        if (root && root.host) { cur = root.host; node = cur.parentElement; continue; }
        const doc = cur && cur.ownerDocument;
        const frame = doc && doc.defaultView ? doc.defaultView.frameElement : null;
        if (frame) { cur = frame; node = frame.parentElement; continue; }
        break;
      }
      return null;
    };
    for (const el of all) {
      if (!isVisible(el)) continue;
      const role = roleOf(el);
      const interactive = el.matches(INTERACTIVE);
      const heading = /^h[1-6]$/.test(el.tagName.toLowerCase());
      const ownText = Array.from(el.childNodes)
        .filter((node) => node.nodeType === 3)
        .map((node) => node.textContent || "")
        .join(" ")
        .replace(/\\s+/g, " ")
        .trim();
      // Text containers with thousands of children produce noise; keep leaves and
      // elements that own text directly.
      const isTextLeaf = ownText.length > 0 && el.children.length <= 2;
      if (!interactive && !heading && !isTextLeaf) continue;
      const name = nameOf(el).slice(0, ${maxName});
      if (!name && !interactive) continue;
      const selector = scriptPath(el);
      if (seen.has(selector)) continue;
      seen.add(selector);
      total += 1;
      if (nodes.length >= ${maxNodes}) continue;
      const field = interactive ? fieldLabelOf(el).slice(0, ${maxName}) : "";
      // Nearest reported ancestor, skipping levels that carried no name, role or
      // text worth reporting. Bounded so an unusual tree cannot walk forever.
      let parent;
      let ancestor = reportedParent(el);
      for (let guard = 0; ancestor && guard < 64; guard += 1) {
        const index = indexOf.get(ancestor);
        if (index !== undefined) { parent = index; break; }
        ancestor = reportedParent(ancestor);
      }
      indexOf.set(el, nodes.length);
      nodes.push({
        role,
        name,
        tag: el.tagName.toLowerCase(),
        selector,
        ...(field && field !== name ? { field } : {}),
        ...(parent === undefined ? {} : { parent }),
        depth: parent === undefined ? 0 : nodes[parent].depth + 1,
        bounds: rectOf(el),
      });
    }
    return {
      url: location.href,
      title: document.title,
      viewport: { width: innerWidth, height: innerHeight },
      nodes,
      total,
      truncated: total > nodes.length,
    };
  })()`;
}

/**
 * Resolves an element to viewport coordinates so the caller can click it with
 * real input events. A synthetic `el.click()` does not carry `isTrusted`, and
 * some frameworks ignore untrusted clicks.
 */
export function buildElementPointExpression(target: TargetInput): string {
  return `(() => {${HELPERS}
    const found = resolveTarget(${targetSource(target)});
    if (!found.el) return { ok: false, reason: found.reason };
    const el = found.el;
    if (!isVisible(el)) return { ok: false, reason: "not-visible" };
    el.scrollIntoView({ block: "center", inline: "center", behavior: "instant" });
    const rect = el.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) return { ok: false, reason: "no-area" };
    // Coordinates are dispatched at the TOP page's viewport, but an element
    // inside an iframe reports rects in its own viewport. Sum the iframe
    // offsets up the ownership chain so the point lands where the element is.
    let offsetX = 0;
    let offsetY = 0;
    let doc = el.ownerDocument;
    while (doc && doc !== document) {
      const frame = doc.defaultView ? doc.defaultView.frameElement : null;
      if (!frame) break;
      const fr = frame.getBoundingClientRect();
      offsetX += fr.x;
      offsetY += fr.y;
      doc = frame.ownerDocument;
    }
    // Marked so the caller can ask, after dispatching the click, whether the
    // events actually landed on this element: an overlay or a scroll shift can
    // redirect them elsewhere, and without the marker that failure looks like
    // "the site ignored the click".
    el.setAttribute("data-ens-click", "1");
    return {
      ok: true,
      x: rect.x + offsetX + rect.width / 2,
      y: rect.y + offsetY + rect.height / 2,
      width: rect.width,
      height: rect.height,
      tag: el.tagName.toLowerCase(),
      text: nameOf(el).slice(0, 80),
      selector: scriptPath(el),
      matchedBy: found.matchedBy,
      matchCount: found.matchCount,
    };
  })()`;
}

/**
 * Reads back where a click landed and clears the target marker.
 *
 * `onTarget` is false when something else received the events — an overlay, a
 * late scroll, a re-render between resolve and dispatch. The caller reports the
 * actually-hit element so the model can react to facts instead of guessing
 * whether a silent page means a broken handler or a missed click.
 */
export function buildClickHitExpression(x: number, y: number): string {
  return `(() => {
    // elementFromPoint stops at a shadow host; descend through open roots so a
    // click that reached a shadow-internal element reads as on-target.
    let el = document.elementFromPoint(${JSON.stringify(x)}, ${JSON.stringify(y)});
    for (let depth = 0; el && el.shadowRoot && depth < 8; depth += 1) {
      const inner = el.shadowRoot.elementFromPoint(${JSON.stringify(x)}, ${JSON.stringify(y)});
      if (!inner || inner === el) break;
      el = inner;
    }
    const marked = el ? el.closest("[data-ens-click]") : null;
    document.querySelectorAll("[data-ens-click]").forEach((n) => n.removeAttribute("data-ens-click"));
    return {
      onTarget: Boolean(marked),
      ...(el ? { tag: el.tagName.toLowerCase(), text: (el.innerText || el.textContent || "").replace(/\\s+/g, " ").trim().slice(0, 80) } : {}),
    };
  })()`;
}

/** Focuses a field so the caller can type into it with `Input.insertText`. */
export function buildFocusExpression(target: TargetInput): string {
  return `(() => {${HELPERS}
    const found = resolveTarget(${targetSource(target)});
    if (!found.el) return { ok: false, reason: found.reason };
    const el = found.el;
    if (!isVisible(el)) return { ok: false, reason: "not-visible" };
    if (typeof el.focus === "function") el.focus();
    if (el.disabled || el.readOnly) return { ok: false, reason: "disabled" };
    if (typeof el.select === "function" && typeof el.value === "string") el.select();
    const tag = el.tagName.toLowerCase();
    // The caller needs to know a field is a password before typing into it, so
    // the audit log can mask a value whose parameter name does not say "secret".
    const inputType = tag === "input" ? (el.getAttribute("type") || "text").toLowerCase() : undefined;
    return {
      ok: true,
      tag,
      selector: scriptPath(el),
      matchedBy: found.matchedBy,
      matchCount: found.matchCount,
      ...(inputType ? { inputType } : {}),
    };
  })()`;
}

/** Reports whether an element exists and is visible, for assertions. */
export function buildVisibilityExpression(target: TargetInput): string {
  return `(() => {${HELPERS}
    const found = resolveTarget(${targetSource(target)});
    if (!found.el) {
      return { exists: false, visible: false, reason: found.reason === "invalid-selector" ? "invalid-selector" : "not-found" };
    }
    const el = found.el;
    if (!isVisible(el)) {
      return {
        exists: true,
        visible: false,
        reason: "hidden",
        bounds: rectOf(el),
        selector: scriptPath(el),
        name: nameOf(el).slice(0, 80),
      };
    }
    return {
      exists: true,
      visible: true,
      bounds: rectOf(el),
      selector: scriptPath(el),
      name: nameOf(el).slice(0, 80),
    };
  })()`;
}

/**
 * 报错文案集中在 core：单测直接断言措辞，main 层只负责把 `LocatorMatches` 的
 * reason 映射成这些句子并抛出。文案是给模型看的行动指引——「给 nth 或加收窄」
 * 就是下一步该做的事。
 */
export function locatorNotFoundText(description: string): string {
  return `找不到 ${description}：页面上没有匹配的元素（text 匹配的是可交互元素和有自身文字的可见元素）`;
}

export function locatorAmbiguousText(description: string, count: number): string {
  return `${description} 匹配 ${count} 个元素：给 nth（0 起，负数从尾数）或加收窄字段（hasText / hasNotText / visible）后再操作`;
}

export function locatorNthOutOfRangeText(
  description: string,
  nth: number,
  count: number,
): string {
  return `${description} 的 nth=${nth} 超出范围：当前匹配 ${count} 个${
    count > 0 ? `（0 到 ${count - 1}，负数从尾数）` : ""
  }`;
}

export function locatorInvalidSelectorText(description: string): string {
  return `${description}：选择器无效`;
}

export function locatorStaleHandleText(handleId: string): string {
  return `句柄 ${handleId} 已失效：页面已导航，句柄失效，请重新 find`;
}

export function locatorUnknownHandleText(handleId: string): string {
  return `句柄不存在：${handleId}。句柄只在本标签页内有效，请先用 find_browser_element 查找`;
}

/** Maps an in-page reason to the wording the caller sees. */
export function locatorErrorText(
  reason: NonNullable<LocatorMatches["reason"]>,
  description: string,
  count: number,
  nth?: number,
): string {
  switch (reason) {
    case "invalid-selector":
      return locatorInvalidSelectorText(description);
    case "ambiguous":
      return locatorAmbiguousText(description, count);
    case "nth-out-of-range":
      return locatorNthOutOfRangeText(description, nth ?? 0, count);
    default:
      return locatorNotFoundText(description);
  }
}

/**
 * Finds every element a locator names and picks one, all inside the page.
 *
 * Two modes answer two different questions. `first: true` is the find/registration
 * pass — it must not fail on multiple matches, because "I see three buttons" is
 * exactly the fact the caller asked for; it picks positionally (nth or 0) so the
 * preview can say which entry a handle would act on. The default mode is the
 * handle-use pass — it must not guess: an explicit nth wins, a single match is
 * taken as-is, and otherwise a recorded text trait aligns the one element the
 * handle has been acting on across re-renders; anything still ambiguous reports
 * `ambiguous` instead of picking.
 */
export function buildFindByLocatorExpression(
  locator: TargetInput,
  options: FindLocatorOptions = {},
): string {
  const mode = options.first === true ? "first" : "use";
  const trait = typeof options.trait === "string" ? options.trait : null;
  const useNth =
    typeof options.nth === "number" && Number.isFinite(options.nth)
      ? Math.trunc(options.nth)
      : null;
  return `(() => {${HELPERS}
    const spec = ${targetSource(locator)};
    const mode = ${JSON.stringify(mode)};
    const trait = ${JSON.stringify(trait)};
    const useNth = ${useNth === null ? "null" : String(useNth)};
    const found = collectMatches(spec);
    const preview = found.matches.slice(0, 50).map((el) => ({
      tag: el.tagName.toLowerCase(),
      text: textOf(el).slice(0, 80),
      visible: isVisible(el),
      rect: rectOf(el),
    }));
    const count = found.matches.length;
    const fail = (reason) => ({
      ok: false,
      reason,
      count,
      matches: preview,
      ...(found.matchedBy ? { matchedBy: found.matchedBy } : {}),
    });
    if (found.reason === "invalid-selector") return fail("invalid-selector");
    if (found.reason === "no-target") return fail("no-target");
    if (!count) return fail("not-found");
    let index = null;
    if (mode === "first") {
      const n = useNth !== null ? useNth : 0;
      const i = n < 0 ? count + n : n;
      if (i < 0 || i >= count) return fail("nth-out-of-range");
      index = i;
    } else {
      if (useNth !== null) {
        const i = useNth < 0 ? count + useNth : useNth;
        if (i < 0 || i >= count) return fail("nth-out-of-range");
        index = i;
      } else if (count === 1) {
        index = 0;
      } else if (trait) {
        // 只有一个命中与登记/上次命中的文本相同才对齐：两个同文本的命中说明
        // 特征失去区分度，宁可让调用方收窄，也不猜。
        const hits = [];
        found.matches.forEach((el, i) => {
          if (textOf(el).slice(0, 80) === trait) hits.push(i);
        });
        if (hits.length === 1) index = hits[0];
      }
      if (index === null) return fail("ambiguous");
    }
    return {
      ok: true,
      count,
      index,
      matches: preview,
      picked: preview[index],
      ...(found.matchedBy ? { matchedBy: found.matchedBy } : {}),
    };
  })()`;
}

/**
 * Polls inside the page until a condition holds.
 *
 * This exists because the alternative costs a full MCP round trip per attempt:
 * a click that triggers an async render needs "sleep, read, sleep, read", and
 * every read is a request. One call that waits page-side turns a dozen round
 * trips into one, and it also removes the gap in which the page state drifts
 * between two calls (a menu closing on blur, an option appearing one frame late).
 */
export function buildWaitExpression(input: {
  condition: WaitCondition;
  target?: TargetInput;
  text?: string;
  timeoutMs: number;
  intervalMs?: number;
}): string {
  const interval = input.intervalMs ?? 150;
  const target = input.target === undefined ? "null" : targetSource(input.target);
  const text = JSON.stringify(input.text ?? "");
  return `(async () => {
    ${HELPERS}
    const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
    const wanted = ${text};
    const needle = norm(wanted);
    const target = ${target};
    const condition = ${JSON.stringify(input.condition)};
    const deadline = Date.now() + ${Math.max(100, Math.trunc(input.timeoutMs))};
    const started = Date.now();
    let lastReason = "not-yet";
    while (Date.now() < deadline) {
      if (condition === "text") {
        const body = document.body ? textOf(document.body) : "";
        if (!needle || norm(body).includes(needle)) return { ok: true, waitedMs: Date.now() - started };
        lastReason = "text-absent";
      } else if (condition === "url") {
        if (!needle || norm(location.href).includes(needle)) {
          return { ok: true, waitedMs: Date.now() - started, matched: location.href };
        }
        lastReason = "url-mismatch";
      } else if (condition === "load") {
        // "complete" covers everything the load event means: subresources
        // settled and the event fired. Pages that keep loading data afterwards
        // stay complete — data fetching is not document loading. matched
        // carries the readyState rather than the URL so a caller can tell a
        // load hit from a url hit, which both return the same shape otherwise.
        if (document.readyState === "complete") {
          return { ok: true, waitedMs: Date.now() - started, matched: document.readyState };
        }
        lastReason = "still-loading";
      } else {
        const found = resolveTarget(target);
        if (condition === "visible") {
          if (found.el && isVisible(found.el)) {
            return {
              ok: true,
              waitedMs: Date.now() - started,
              matched: found.matchedBy,
            };
          }
          lastReason = found.reason || "not-visible";
        } else if (condition === "hidden") {
          // "No longer there" is success: a toast disappears from the DOM as
          // often as it fades out.
          if (!found.el) return { ok: true, waitedMs: Date.now() - started };
          if (!isVisible(found.el)) return { ok: true, waitedMs: Date.now() - started };
          lastReason = "still-visible";
        } else if (condition === "value") {
          if (!found.el) {
            lastReason = found.reason || "not-found";
          } else {
            const value = String(found.el.value ?? found.el.textContent ?? "");
            if (norm(value).includes(needle)) {
              return { ok: true, waitedMs: Date.now() - started, matched: found.matchedBy };
            }
            lastReason = "value-mismatch";
          }
        } else {
          return { ok: false, waitedMs: 0, reason: "unknown-condition" };
        }
      }
      await wait(${interval});
    }
    return { ok: false, waitedMs: Date.now() - started, timedOut: true, timedOutAt: "page", reason: lastReason };
  })()`;
}

/**
 * Sets the value of a `<select>` (or a combobox that exposes one) by option
 * text, and reports what actually landed.
 *
 * Using the native setter plus `input`/`change` is what makes React, Vue and
 * Naive UI update: assigning `el.value` alone leaves their internal state stale,
 * so the visible box shows the new option while the form submits the old one.
 */
export function buildSelectExpression(target: TargetInput, option: string): string {
  return `(() => {${HELPERS}
    const found = resolveTarget(${targetSource(target)});
    if (!found.el) return { ok: false, reason: found.reason };
    let el = found.el;
    if (el.tagName.toLowerCase() !== "select") {
      el = el.querySelector ? el.querySelector("select") : null;
    }
    if (!el) return { ok: false, reason: "not-a-select" };
    // Trim + whitespace-fold, no case folding, no substring: option values are
    // enumerations where case can be meaningful, and "广州" must not match
    // "广州市" — an approximate hit here picks the wrong row of real data.
    const clean = (s) => String(s ?? "").replace(/\\s+/g, " ").trim();
    const wanted = clean(${JSON.stringify(option)});
    const options = Array.from(el.options || []);
    const match =
      options.find((item) => clean(item.textContent) === wanted) ??
      options.find((item) => clean(item.value) === wanted);
    if (!match) {
      return {
        ok: false,
        reason: "option-not-found",
        available: options.slice(0, 20).map((item) => clean(item.textContent)).filter(Boolean),
      };
    }
    const view = el.ownerDocument.defaultView;
    const proto = view ? view.HTMLSelectElement.prototype : HTMLSelectElement.prototype;
    const descriptor = Object.getOwnPropertyDescriptor(proto, "value");
    if (descriptor && descriptor.set) descriptor.set.call(el, match.value);
    else el.value = match.value;
    el.dispatchEvent(new Event("input", { bubbles: true }));
    el.dispatchEvent(new Event("change", { bubbles: true }));
    return {
      ok: true,
      matchedBy: found.matchedBy,
      value: match.value,
      text: clean(match.textContent),
      selector: scriptPath(el),
      matchCount: found.matchCount,
    };
  })()`;
}

/**
 * Reads a value out of the page for a flow's `read` step.
 *
 * It returns the text a person would see, not `outerHTML`: a flow substitutes
 * this into later steps (an order number, a generated account name), and markup
 * would poison the next field.
 */
export function buildReadExpression(target: TargetInput): string {
  return `(() => {${HELPERS}
    let found = resolveTarget(${targetSource(target)});
    if (!found.el) {
      // Reading is not limited to controls: capture an order number out of a
      // paragraph is the common case, and that element is not interactive.
      const spec = ${targetSource(target)};
      if (typeof spec === "object" && spec.text) {
        const el = textElement(spec.text, spec.exact === true);
        if (el) found = { el, matchedBy: "text" };
      }
    }
    if (!found.el) return { ok: false, reason: found.reason };
    const el = found.el;
    const tag = el.tagName.toLowerCase();
    const value =
      tag === "input" || tag === "textarea" || tag === "select"
        ? String(el.value ?? "")
        : textOf(el);
    return {
      ok: true,
      value: value.trim().slice(0, 500),
      matchedBy: found.matchedBy,
      selector: scriptPath(el),
    };
  })()`;
}

/** Scrolls a tab to the top; used to compare pages from a known position. */
export const RESET_SCROLL_EXPRESSION = "(() => { window.scrollTo(0, 0); return true; })()";

/** Waits for the document to reach a stable size, then reports it. */
export function buildStabilityExpression(): string {
  return `(async () => {
    const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
    let last = -1;
    let stable = 0;
    for (let round = 0; round < 30; round += 1) {
      const height = document.documentElement.scrollHeight;
      if (height === last) stable += 1;
      else { stable = 0; last = height; }
      if (stable >= 2) return { stable: true, height };
      await wait(120);
    }
    return { stable: false, height: last };
  })()`;
}

/**
 * Resolves a target to the file input it names, for `DOM.setFileInputFiles`.
 *
 * Two things the caller needs back and cannot get from a bare point: whether the
 * element really is a file input (a click on some other element would do
 * nothing), and whether it accepts multiple files. Both are reported so the
 * caller can be told to fix its target instead of watching an upload silently
 * do nothing.
 */
export function buildFileInputExpression(target: TargetInput): string {
  return `(() => {${HELPERS}
    const spec = ${targetSource(target)};
    const found = resolveTarget(spec);
    if (!found.el) {
      // A file input is often hidden behind a styled button, so a text match on
      // the visible button is a legitimate way to ask for it. Try the label path
      // before giving up.
      if (typeof spec === "object" && (spec.text || spec.label)) {
        const wanted = spec.text || spec.label;
        const all = [];
        eachRoot((root) => { try { root.querySelectorAll('input[type=file]').forEach((el) => all.push(el)); } catch {} });
        const scopeText = (el) => {
          let node = el;
          for (let depth = 0; node && depth < 6; depth += 1, node = node.parentElement) {
            if (scoreName(textOf(node), wanted, spec.exact === true) > 0) return node;
          }
          return null;
        };
        const hit = all.find((el) => scopeText(el));
        if (hit) return { ok: true, multiple: hit.multiple === true, accept: (hit.getAttribute("accept") || "").slice(0, 200), disabled: hit.disabled === true, matchedBy: "nearby-text" };
      }
      return { ok: false, reason: found.reason === "invalid-selector" ? "invalid-selector" : "not-found" };
    }
    const el = found.el;
    const tag = el.tagName.toLowerCase();
    const type = (el.getAttribute("type") || "").toLowerCase();
    if (tag !== "input" || type !== "file") {
      return { ok: false, reason: "not-a-file-input", tag, matchedBy: found.matchedBy };
    }
    if (el.disabled) return { ok: false, reason: "disabled", tag, matchedBy: found.matchedBy };
    return {
      ok: true,
      multiple: el.multiple === true,
      accept: (el.getAttribute("accept") || "").slice(0, 200),
      matchedBy: found.matchedBy,
      matchCount: found.matchCount,
      selector: scriptPath(el),
    };
  })()`;
}

/**
 * Resolves both ends of a drag to viewport points.
 *
 * Resolved together rather than one call per end so the two points describe the
 * same layout: a re-render between two round trips could move the target and the
 * press would start from a stale coordinate.
 */
export function buildDragPointsExpression(from: TargetInput, to: TargetInput): string {
  return `(() => {${HELPERS}
    const start = resolveTarget(${targetSource(from)});
    if (!start.el) return { ok: false, reason: "from-" + (start.reason || "not-found") };
    if (!isVisible(start.el)) return { ok: false, reason: "from-hidden" };
    const end = resolveTarget(${targetSource(to)});
    if (!end.el) return { ok: false, reason: "to-" + (end.reason || "not-found") };
    if (!isVisible(end.el)) return { ok: false, reason: "to-hidden" };
    const centre = (el) => {
      const rect = el.getBoundingClientRect();
      return { x: Math.round(rect.x + rect.width / 2), y: Math.round(rect.y + rect.height / 2) };
    };
    const a = centre(start.el);
    const b = centre(end.el);
    return {
      ok: true,
      from: a,
      to: b,
      fromTag: start.el.tagName.toLowerCase(),
      toTag: end.el.tagName.toLowerCase(),
      fromText: textOf(start.el).slice(0, 60),
      toText: textOf(end.el).slice(0, 60),
      fromMatchCount: start.matchCount,
      toMatchCount: end.matchCount,
    };
  })()`;
}

/**
 * Reads a checkbox's or radio's state, and flips it when asked.
 *
 * Clicking a checkbox to toggle it is not the same as setting it: the click
 * routes through the label, the wrapper, the framework's own handler, and any
 * one of them can prevent the default. So the state is read in the page, and only
 * a mismatch is clicked — which is what makes `check` idempotent, and what stops
 * a second call from unchecking what the first one set.
 */
export function buildCheckExpression(target: TargetInput, desired: boolean): string {
  return `(() => {${HELPERS}
    const found = resolveTarget(${targetSource(target)});
    if (!found.el) return { ok: false, reason: found.reason === "invalid-selector" ? "invalid-selector" : "not-found" };
    const el = found.el;
    const tag = el.tagName.toLowerCase();
    const type = (el.getAttribute("type") || "").toLowerCase();
    if (tag !== "input" || (type !== "checkbox" && type !== "radio")) {
      return { ok: false, reason: "not-a-toggle", tag, type: type || undefined, matchedBy: found.matchedBy };
    }
    if (el.disabled) return { ok: false, reason: "disabled" };
    if (!isVisible(el)) return { ok: false, reason: "not-visible" };
    const before = el.checked === true;
    const desired = ${desired ? "true" : "false"};
    if (before === desired) return { ok: true, changed: false, checked: before, tag, type, selector: scriptPath(el), matchCount: found.matchCount };
    el.click();
    const after = el.checked === true;
    return {
      ok: true,
      changed: after !== before,
      checked: after,
      tag,
      type,
      selector: scriptPath(el),
      matchCount: found.matchCount,
      // A click that did not change the box is a fact worth reporting: a
      // disabled label wrapper or a handler calling preventDefault is exactly the
      // case where the caller otherwise assumes it worked.
      ...(after === desired ? {} : { stuckAt: before }),
    };
  })()`;
}

/**
 * Everything about one element that a caller can act on.
 *
 * This exists because the alternatives are both bad: `read` gives one string and
 * no way to ask about an attribute, and `evaluate_browser_page` makes the caller
 * write DOM code — the part that goes stale the moment the page changes shape.
 * One call that answers "what is this element, really" replaces a dozen ad-hoc
 * scripts.
 *
 * `attributes` is capped deliberately: a styled element can carry hundreds of
 * generated class names, and shipping them all costs tokens without answering
 * anything. The ones a caller needs to *act* are kept even when the cap is hit.
 */
export function buildElementInfoExpression(target: TargetInput): string {
  return `(() => {${HELPERS}
    const found = resolveTarget(${targetSource(target)});
    if (!found.el) return { ok: false, reason: found.reason === "invalid-selector" ? "invalid-selector" : "not-found" };
    const el = found.el;
    const tag = el.tagName.toLowerCase();
    const type = (el.getAttribute("type") || "").toLowerCase();
    const KEEP = ["type", "name", "value", "placeholder", "href", "src", "alt", "title", "role", "aria-label", "aria-checked", "aria-expanded", "aria-disabled", "aria-selected", "data-testid", "data-test", "data-cy", "for", "disabled", "readonly", "required", "multiple", "checked", "selected", "maxlength", "min", "max", "step", "pattern", "target", "rel", "lang", "dir"];
    const attributes = {};
    for (const attr of Array.from(el.attributes || [])) {
      if (KEEP.includes(attr.name) || attr.name.startsWith("aria-") || attr.name.startsWith("data-")) {
        attributes[attr.name] = String(attr.value).slice(0, 200);
      }
    }
    const isFormControl = tag === "input" || tag === "textarea" || tag === "select";
    const state = {
      visible: isVisible(el),
      enabled: el.disabled !== true && el.getAttribute("aria-disabled") !== "true",
      focused: el === document.activeElement,
      checked: typeof el.checked === "boolean" ? el.checked : undefined,
      selected: typeof el.selected === "boolean" ? el.selected : undefined,
      expanded: el.getAttribute("aria-expanded") === null ? undefined : el.getAttribute("aria-expanded") === "true",
      readOnly: el.readOnly === true,
      // One meaning for "editable": a form control that accepts input, or
      // contenteditable text. Reporting contenteditable alone would call a plain
      // <input type=text> not-editable while readOnly:false — a contradiction.
      editable: (isFormControl && el.disabled !== true && el.readOnly !== true) || el.isContentEditable === true,
    };
    return {
      ok: true,
      tag,
      role: roleOf(el),
      name: nameOf(el).slice(0, 160),
      text: textOf(el).slice(0, 200),
      selector: scriptPath(el),
      matchedBy: found.matchedBy,
      bounds: rectOf(el),
      state,
      attributes,
      // The value of a control, which is what "what is in this field" means.
      ...(tag === "input" || tag === "textarea" || tag === "select"
        ? { value: String(el.value ?? "").slice(0, 500) }
        : {}),
      ...(tag === "input" || tag === "textarea" || tag === "select" ? { inputType: type || "text" } : {}),
      ...(el.parentElement ? { parentTag: el.parentElement.tagName.toLowerCase() } : {}),
      ...(el.children.length ? { childCount: el.children.length } : {}),
    };
  })()`;
}

/**
 * Reads one attribute, a list of them, or the element's whole value.
 *
 * Separate from `buildElementInfoExpression` on purpose. The common use is "did
 * this class or aria attribute change" — a question asked in a loop, and paying
 * for the full info payload every time would make polling expensive. `name`
 * omitted means "give me the text/value", which is the other common question.
 */
export function buildAttributeExpression(target: TargetInput, names: string[] | undefined): string {
  const wanted = names === undefined ? "null" : JSON.stringify(names.slice(0, 40));
  return `(() => {${HELPERS}
    const found = resolveTarget(${targetSource(target)});
    if (!found.el) return { ok: false, reason: found.reason === "invalid-selector" ? "invalid-selector" : "not-found" };
    const el = found.el;
    const names = ${wanted};
    const tag = el.tagName.toLowerCase();
    if (names === null) {
      // No attribute named: answer the question people usually mean instead,
      // which is "what does this element say".
      const isControl = tag === "input" || tag === "textarea" || tag === "select";
      return {
        ok: true,
        selector: scriptPath(el),
        ...(isControl
          ? { value: String(el.value ?? "").slice(0, 500) }
          : { text: textOf(el).slice(0, 2000) }),
      };
    }
    const values = {};
    for (const name of names) {
      const value = el.getAttribute(name);
      values[name] = value === null ? null : String(value).slice(0, 1000);
    }
    return { ok: true, selector: scriptPath(el), attributes: values };
  })()`;
}

/**
 * The resolved element's box, or null when it does not exist.
 *
 * Separate from `buildElementPointExpression` because the point is what an input
 * event needs and the box is what a screenshot needs: a clipped capture has to
 * know all four edges, and deriving the size from a centre point is not possible.
 */
export function buildElementRectExpression(target: TargetInput): string {
  return `(() => {
    ${HELPERS}
    const found = resolveTarget(${targetSource(target)});
    if (!found.el) return null;
    const rect = found.el.getBoundingClientRect();
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    /*
     * The intersection is computed here rather than in main.
     *
     * getBoundingClientRect() returns viewport-relative coordinates that stay
     * numerically valid far outside the viewport — an element 3000px down a page
     * reports y = 3000, not "not visible". Intersecting against the viewport is
     * what turns that into an answer, and the ratio the page needs
     * (devicePixelRatio) is only knowable from inside the page.
     */
    const left = Math.max(0, Math.round(rect.x));
    const top = Math.max(0, Math.round(rect.y));
    const right = Math.min(vw, Math.round(rect.x + rect.width));
    const bottom = Math.min(vh, Math.round(rect.y + rect.height));
    return {
      x: Math.round(rect.x),
      y: Math.round(rect.y),
      width: Math.round(rect.width),
      height: Math.round(rect.height),
      viewportWidth: vw,
      viewportHeight: vh,
      devicePixelRatio: window.devicePixelRatio || 1,
      clip: right - left >= 1 && bottom - top >= 1 ? { x: left, y: top, width: right - left, height: bottom - top } : null,
    };
  })()`;
}
